#!/usr/bin/env bash
set -euo pipefail

file="${1:-servers.json}"
readme="${2:-README.md}"

{
	cat <<'EOF'
# Master Server List

<!-- Generated by scripts/generate-readme.sh. Edit servers.json for catalogue data or the generator for this introduction. -->

Official and community master servers for multiplayer games, including replacements for discontinued services.

**[Browse live status and server counts](https://ismygameserver.online/masters)**

## Status

Masters are checked daily. This README is a snapshot, updated when a status changes; counts may be older than the latest check.

| Status | Meaning |
|---|---|
| ✅ Online | Passed its configured check; TCP-only checks do not verify game lists |
| ❔ DNS only | Hostname resolves; no protocol query is available yet |
| ⚠️ No response | Check failed, including connection or query errors |
| ❌ No DNS | Checking network could not resolve a usable address |

**Official** means run by the developer, publisher or game's own project; **Community** means independently run. Retired masters are no longer checked and can be removed from configs. Retirement dates are sourced shutdown dates or the first failed check, as labelled.

<details>
<summary>Data and checker details</summary>

- [Catalogue](https://dgibbs64.github.io/Master-Server-List/servers.json): hosts, protocols and check results.
- [Server addresses](https://dgibbs64.github.io/Master-Server-List/servers-list.json): merged per game with duplicates removed, where supported.
- [History](https://dgibbs64.github.io/Master-Server-List/history.json): 180 days of results, stored on the `history` branch.

Checks rotate between hosts with a 30-second cooldown shared by IPv4 address. Failures get two later retries, delayed at least 30 and 60 seconds. Refused TCP endpoints are checked once per pass. Override timing with `MASTER_MIN_INTERVAL` and `MASTER_RETRY_DELAY` (seconds); `check_error` records failure reasons. Pacing does not guarantee a response or establish a provider's rate limit.

</details>

To contribute, edit `servers.json`, run `./scripts/generate-readme.sh` and open a pull request.

EOF
	jq -r '
		def status_label: {"online": "✅ Online", "dns-only": "❔ DNS only", "no-response": "⚠️ No response", "no-dns": "❌ No DNS"}[. // ""] // "Unchecked";
		def status_rank: {"online": 0, "dns-only": 1, "no-response": 2, "no-dns": 3}[. // ""] // 4;
		def anchor: ascii_downcase | gsub("[^a-z0-9 -]"; "") | gsub(" "; "-");
		"Status as of: \(.checked // "never")\n",
		"## Games\n",
		"<details>\n<summary>Browse games</summary>\n",
		(.games[] | "- [\(.name)](#\(.name | anchor))"),
		"\n</details>\n",
		(.games[]
			| "## \(.name)\n",
			(if .notes then "\(.notes)\n" else empty end),
			(if (.masters | length) > 0 then
				"| Master server | Run by | Status | Servers | Last seen |",
				"|---|---|---|---|---|",
				(.masters | sort_by([(.status | status_rank), -(.servers // -1)])[] | "| `\(.host)\(if .port then ":\(.port)" else "" end)` | \(if .official == true then "Official" elif .official == false then "Community" else "-" end) | \(.status | status_label) | \(.servers // "-") | \(.last_seen // "Never") |"),
				""
			else empty end),
			(if (.retired // [] | length) > 0 then
				"### Retired master servers\n",
				"| Master server | Run by | Gone | Notes |",
				"|---|---|---|---|",
				(.retired[] | "| `\(.host)\(if .port then ":\(.port)" else "" end)` | \(if .official then "Official" else "Community" end) | \(if .shutdown then "Shut down \(.shutdown)" else "Not answering since \(.down_since)" end) | \(.reason)\(if .source then " [Source](\(.source))" else "" end) |"),
				""
			else empty end))
	' "${file}" | sed '$ { /^$/d }'
} >"${readme}"
